"""Poll Prometheus for Claude Code session state derived from Loki recording rules."""

import json
import logging
import urllib.parse
import urllib.request
from typing import NamedTuple

from claude_dashboard import config
from claude_dashboard.config import StatusState

logger = logging.getLogger(__name__)

_STATE_PRIORITY = config.STATE_PRIORITY

# Codex publishes its own metric family from the same Loki ruler. Session ids
# are UUIDs and do not collide across harnesses, so both families feed one dict.
# The codex rules currently group by (session_id, project, cwd, model) only —
# no host_name, so a codex session on another machine never registers as a
# remote row (_add_remote_session bails on an empty host). Local codex is
# matched by session_id from discover_codex_sessions() and is unaffected.
_METRIC_TO_STATE = {
    "claude_session_permission": StatusState.PERMISSION_REQUIRED,
    "claude_session_working": StatusState.WORKING,
    "claude_session_ready": StatusState.READY,
    "codex_session_permission": StatusState.PERMISSION_REQUIRED,
    "codex_session_working": StatusState.WORKING,
    "codex_session_ready": StatusState.READY,
}

_METRICS = list(_METRIC_TO_STATE.keys())

_TIMEOUT_SECONDS = 2


class SessionState(NamedTuple):
    state: StatusState
    host_name: str
    project: str
    location: str = ""
    headless: bool = False
    sandbox_source: str = ""
    sandbox_openshell_name: str = ""


def poll_session_states(*, prometheus_url: str) -> dict[str, SessionState]:
    """Query Prometheus for claude_session_* recording rule metrics.

    Returns dict mapping session_id to SessionState (highest-priority state
    wins when multiple metrics are truthy for the same session).

    Metrics checked (highest priority first):
      1. claude_session_permission > 0 → PERMISSION_REQUIRED
      2. claude_session_working > 0 → WORKING
      3. claude_session_ready > 0 → READY
    """
    candidates: dict[str, SessionState] = {}

    for metric_name in _METRICS:
        state = _METRIC_TO_STATE[metric_name]
        results = _query_metric(prometheus_url=prometheus_url, metric=metric_name)
        for result in results:
            labels = result.get("metric", {})
            session_id = labels.get("session_id", "")
            if not session_id:
                continue
            value = _parse_value(result)
            if value is None or value <= 0:
                continue
            host_name = labels.get("host_name", "")
            project = labels.get("project", "")
            location = labels.get("location", "")
            # Self-made marker: claude-wrapper.sh sets headless=true for
            # -p/--print runs; recording rules carry it through. Absent
            # label (direct runs, old wrappers) = interactive.
            headless = labels.get("headless", "") == "true"
            candidate = SessionState(
                state=state,
                host_name=host_name,
                project=project,
                location=location,
                headless=headless,
                sandbox_source=labels.get("sandbox_source", ""),
                sandbox_openshell_name=labels.get("sandbox_openshell_name", ""),
            )
            existing = candidates.get(session_id)
            if existing is None or _wins(candidate, existing):
                candidates[session_id] = candidate

    return candidates


def _identity_labels(state: SessionState) -> int:
    """Count sandbox identity labels present — a proxy for label-shape age."""
    return bool(state.sandbox_openshell_name) + bool(state.sandbox_source)


def _wins(candidate: SessionState, existing: SessionState) -> bool:
    """True when candidate should replace existing for the same session_id.

    Richer sandbox identity wins BEFORE state priority. Adding a label to a
    recording rule starts a new series while the old label-less one lingers,
    so one session reports under two label shapes at once — and the stale
    shape can be stuck in a state that will never be superseded, because the
    rules compare timestamps within a label set and no further events carry
    the old shape. A false permission_required outlives its window that way.
    Preferring the richer shape is the closest thing to "most recent" the
    metrics offer: `ready`/`permission` values are event timestamps but
    `working` is a count, so values are not comparable across metrics.

    Equal identity (both shapes the same, or a plain host session with no
    sandbox labels at all) falls through to state priority as before.
    """
    if _identity_labels(candidate) != _identity_labels(existing):
        return _identity_labels(candidate) > _identity_labels(existing)
    return _STATE_PRIORITY[candidate.state] < _STATE_PRIORITY[existing.state]


def _query_metric(*, prometheus_url: str, metric: str) -> list[dict]:
    """Query a single instant metric from Prometheus."""
    url = f"{prometheus_url}/api/v1/query?query={urllib.parse.quote(metric)}"
    try:
        req = urllib.request.Request(url)
        with urllib.request.urlopen(req, timeout=_TIMEOUT_SECONDS) as resp:
            data = json.loads(resp.read())
            if data.get("status") != "success":
                logger.debug("prometheus query %s: status=%s", metric, data.get("status"))
                return []
            return data.get("data", {}).get("result", [])
    except Exception:
        logger.debug("prometheus query %s failed", metric, exc_info=True)
        return []


def _parse_value(result: dict) -> float | None:
    """Extract numeric value from a Prometheus instant query result."""
    try:
        v = float(result["value"][1])
        if v != v:  # NaN check
            return None
        return v
    except (KeyError, IndexError, TypeError, ValueError):
        return None
